17	/**
18	 * Converts an ESLint JSON config to a flat config.
19	 * Deletes the original file along with .eslintignore if it exists.
20	 */
21	export function convertEslintJsonToFlatConfig(
22	  tree: Tree,
23	  root: string,
24	  config: ESLint.ConfigData,
25	  ignorePaths: string[],
26	  format: 'cjs' | 'mjs'
27	): { content: string; addESLintRC: boolean; addESLintJS: boolean } {
28	  const importsMap = new Map<string, string>();
29	  const exportElements: ts.Expression[] = [];
30	  let isFlatCompatNeeded = false;
31	  let isESLintJSNeeded = false;
32	  let combinedConfig: ts.PropertyAssignment[] = [];
33	  let languageOptions: ts.PropertyAssignment[] = [];
34	
35	  // exclude dist and eslint config from being linted, which matches the default for new workspaces
36	  exportElements.push(
37	    generateAst({
38	      ignores: ['**/dist', '**/out-tsc'],
39	    })
40	  );
41	
42	  if (config.extends) {
43	    const extendsResult = addExtends(
44	      importsMap,
45	      exportElements,
46	      config,
47	      format
48	    );
49	    isFlatCompatNeeded = extendsResult.isFlatCompatNeeded;
50	    isESLintJSNeeded = extendsResult.isESLintJSNeeded;
51	  }
52	
53	  if (config.plugins) {
