55	  }
56	
57	  if (config.parser) {
58	    const imp = config.parser;
59	    const parserName = names(imp).propertyName;
60	    importsMap.set(imp, parserName);
61	
62	    languageOptions.push(
63	      ts.factory.createPropertyAssignment(
64	        'parser',
65	        ts.factory.createIdentifier(parserName)
66	      )
67	    );
68	  }
69	
70	  if (config.parserOptions) {
71	    languageOptions.push(
72	      ts.factory.createPropertyAssignment(
73	        'parserOptions',
74	        generateAst(config.parserOptions)
75	      )
76	    );
77	  }
78	
79	  if (config.globals || config.env) {
80	    if (config.env) {
81	      importsMap.set('globals', 'globals');
82	    }
83	
84	    languageOptions.push(
85	      ts.factory.createPropertyAssignment(
86	        'globals',
87	        ts.factory.createObjectLiteralExpression([
88	          ...Object.keys(config.env || {}).map((env) =>
89	            ts.factory.createSpreadAssignment(
90	              ts.factory.createPropertyAccessExpression(
