93	              )
94	            )
95	          ),
96	          ...Object.keys(config.globals || {}).map((key) =>
97	            ts.factory.createPropertyAssignment(
98	              key,
99	              generateAst(config.globals[key])
100	            )
101	          ),
102	        ])
103	      )
104	    );
105	  }
106	
107	  if (config.settings) {
108	    combinedConfig.push(
109	      ts.factory.createPropertyAssignment(
