119	  ) {
120	    combinedConfig.push(
121	      ts.factory.createPropertyAssignment(
122	        'linterOptions',
123	        generateAst({
124	          noInlineConfig: config.noInlineConfig,
125	          reportUnusedDisableDirectives: config.reportUnusedDisableDirectives,
126	        })
127	      )
128	    );
129	  }
130	
131	  if (languageOptions.length > 0) {
132	    combinedConfig.push(
133	      ts.factory.createPropertyAssignment(
134	        'languageOptions',
135	        ts.factory.createObjectLiteralExpression(
136	          languageOptions,
137	          languageOptions.length > 1
138	        )
139	      )
140	    );
141	  }
142	
143	  if (combinedConfig.length > 0) {
144	    exportElements.push(
145	      ts.factory.createObjectLiteralExpression(
146	        combinedConfig,
147	        combinedConfig.length > 1
148	      )
149	    );
150	  }
151	
152	  if (config.rules) {
153	    exportElements.push(generateAst({ rules: config.rules }));
154	  }
155	
156	  if (config.overrides) {
157	    config.overrides.forEach((override) => {
158	      if (override.extends) {
159	        const extendsArr = Array.isArray(override.extends)
160	          ? override.extends
161	          : [override.extends];
162	        const mapped = extendsArr.map((e) => ({
163	          original: e,
164	          flatConfig: mapNxPluginToFlatConfig(e),
165	        }));
166	        const nxExtends = mapped.filter((m) => m.flatConfig);
167	        const nonNxExtends = mapped
168	          .filter((m) => !m.flatConfig)
169	          .map((m) => m.original);
170	
171	        if (nxExtends.length > 0) {
172	          const nxVar = (importsMap.get('@nx/eslint-plugin') as string) ?? 'nx';
173	          importsMap.set('@nx/eslint-plugin', nxVar);
174	          nxExtends.forEach((ext) => {
175	            exportElements.push(
176	              generateFlatPredefinedConfig(ext.flatConfig, nxVar, true)
177	            );
178	          });
179	
180	          // Build remaining override without Nx extends
181	          const remainingOverride = { ...override };
182	          if (nonNxExtends.length > 0) {
183	            remainingOverride.extends = nonNxExtends;
184	          } else {
185	            delete remainingOverride.extends;
186	          }
187	
188	          // Emit remaining override if it has content beyond files and empty rules
189	          const {
190	            files: _files,
191	            rules: remainingRules,
192	            ...remainingRest
193	          } = remainingOverride;
194	          const hasNonEmptyRules =
195	            remainingRules && Object.keys(remainingRules).length > 0;
196	          if (Object.keys(remainingRest).length > 0 || hasNonEmptyRules) {
197	            if (
198	              remainingOverride.env ||
199	              remainingOverride.extends ||
200	              remainingOverride.plugins ||
201	              remainingOverride.parser
202	            ) {
203	              isFlatCompatNeeded = true;
204	            }
205	            exportElements.push(
206	              generateFlatOverride(remainingOverride, format)
207	            );
208	          }
209	          return;
210	        }
211	      }
212	
213	      if (
214	        override.env ||
215	        override.extends ||
216	        override.plugins ||
217	        override.parser
218	      ) {
219	        isFlatCompatNeeded = true;
220	      }
221	      exportElements.push(generateFlatOverride(override, format));
222	    });
223	  }
224	
225	  if (config.ignorePatterns) {
226	    const patterns = (
227	      Array.isArray(config.ignorePatterns)
228	        ? config.ignorePatterns
229	        : [config.ignorePatterns]
230	    ).filter((pattern) => !['**/*', '!**/*', 'node_modules'].includes(pattern)); // these are useless in a flat config
231	    if (patterns.length > 0) {
232	      exportElements.push(
233	        generateAst({
234	          ignores: patterns.map((path) => mapFilePath(path)),
235	        })
236	      );
237	    }
238	  }
239	
240	  for (const ignorePath of ignorePaths) {
241	    if (tree.exists(ignorePath)) {
242	      const patterns = tree
243	        .read(ignorePath, 'utf-8')
244	        .split(/\r\n|\r|\n/)
245	        .filter((line) => line.length > 0 && line !== 'node_modules')
246	        .map((path) => mapFilePath(path));
247	      if (patterns.length > 0) {
248	        exportElements.push(generateAst({ ignores: patterns }));
249	      }
250	    }
251	  }
