31	export async function convertToFlatConfigGenerator(
32	  tree: Tree,
33	  options: ConvertToFlatConfigGeneratorSchema
34	): Promise<void | GeneratorCallback> {
35	  const eslintFile = findEslintFile(tree);
36	  if (!eslintFile) {
37	    throw new Error('Could not find root eslint file');
38	  }
39	  if (eslintFile.endsWith('.js')) {
40	    throw new Error(
41	      'Only json and yaml eslint config files are supported for conversion'
42	    );
43	  }
44	
45	  options.eslintConfigFormat ??= 'mjs';
46	
47	  const eslintIgnoreFiles = new Set<string>(['.eslintignore']);
48	
49	  // convert root eslint config to eslint.config.cjs or eslint.base.config.mjs based on eslintConfigFormat
50	  convertRootToFlatConfig(tree, eslintFile, options.eslintConfigFormat);
51	
52	  // convert project eslint files to eslint.config.cjs
53	  const projects = getProjects(tree);
54	  for (const [project, projectConfig] of projects) {
55	    convertProjectToFlatConfig(
56	      tree,
57	      project,
58	      projectConfig,
59	      readNxJson(tree),
60	      eslintIgnoreFiles,
61	      options.eslintConfigFormat
62	    );
63	  }
64	
65	  // delete all .eslintignore files
66	  for (const ignoreFile of eslintIgnoreFiles) {
67	    tree.delete(ignoreFile);
68	  }
69	
70	  // replace references in nx.json
71	  updateNxJsonConfig(tree, options.eslintConfigFormat);
72	  // install missing packages
73	
74	  if (!options.skipFormat) {
75	    await formatFiles(tree);
76	  }
77	
78	  return () => installPackagesTask(tree);
79	}
