83	function convertRootToFlatConfig(
84	  tree: Tree,
85	  eslintFile: string,
86	  format: 'cjs' | 'mjs'
87	) {
88	  if (/\.base\.(js|json|yml|yaml)$/.test(eslintFile)) {
89	    convertConfigToFlatConfig(
90	      tree,
91	      '',
92	      eslintFile,
93	      `eslint.base.config.${format}`,
94	      format
95	    );
96	  }
97	  convertConfigToFlatConfig(
98	    tree,
99	    '',
100	    eslintFile.replace('.base.', '.'),
101	    `eslint.config.${format}`,
102	    format
103	  );
104	}
105	
106	const ESLINT_LINT_EXECUTOR = '@nx/eslint:lint';
107	
108	function isEslintTarget(target: { executor?: string; command?: string }) {
109	  return (
110	    target.executor === ESLINT_LINT_EXECUTOR ||
111	    target.command?.includes('eslint')
112	  );
113	}
114	
115	function convertProjectToFlatConfig(
116	  tree: Tree,
117	  project: string,
118	  projectConfig: ProjectConfiguration,
119	  nxJson: NxJsonConfiguration,
120	  eslintIgnoreFiles: Set<string>,
121	  format: 'cjs' | 'mjs'
122	) {
123	  const eslintFile = findEslintFile(tree, projectConfig.root);
124	  if (!eslintFile || eslintFile.endsWith('.js')) {
125	    return;
126	  }
127	
128	  // Clean up obsolete target options and detect explicit ESLint targets
129	  let ignorePath: string | undefined;
130	  const eslintTargets = projectConfig.targets
131	    ? Object.keys(projectConfig.targets).filter((t) =>
132	        isEslintTarget(projectConfig.targets[t])
133	      )
134	    : [];
135	  for (const target of eslintTargets) {
136	    if (projectConfig.targets[target].options?.eslintConfig) {
137	      delete projectConfig.targets[target].options.eslintConfig;
138	    }
139	    if (projectConfig.targets[target].options?.ignorePath) {
140	      ignorePath = projectConfig.targets[target].options.ignorePath;
141	      delete projectConfig.targets[target].options.ignorePath;
142	    }
143	  }
144	  if (eslintTargets.length > 0) {
145	    updateProjectConfiguration(tree, project, projectConfig);
146	  }
147	  const hasEslintTargetDefaults =
148	    projectConfig.targets &&
149	    Object.keys(nxJson.targetDefaults || {}).some(
150	      (t) =>
151	        (t === ESLINT_LINT_EXECUTOR ||
152	          isEslintTarget(nxJson.targetDefaults[t])) &&
153	        projectConfig.targets[t]
154	    );
155	
156	  if (
157	    eslintTargets.length === 0 &&
158	    !hasEslintTargetDefaults &&
159	    !hasEslintPlugin(tree)
160	  ) {
161	    logger.warn(
162	      `Skipping "${project}": found ${eslintFile} but no ESLint lint target detected. Convert manually if needed.`
163	    );
164	    return;
165	  }
166	
167	  convertConfigToFlatConfig(
168	    tree,
169	    projectConfig.root,
170	    eslintFile,
171	    `eslint.config.${format}`,
172	    format,
173	    ignorePath
174	  );
175	  eslintIgnoreFiles.add(`${projectConfig.root}/.eslintignore`);
176	  if (ignorePath) {
177	    eslintIgnoreFiles.add(ignorePath);
178	  }
179	}
