181	// update names of eslint files in nx.json
182	// and remove eslintignore
183	function updateNxJsonConfig(tree: Tree, format: 'cjs' | 'mjs') {
184	  if (tree.exists('nx.json')) {
185	    updateJson(tree, 'nx.json', (json: NxJsonConfiguration) => {
186	      if (json.targetDefaults?.lint?.inputs) {
187	        const inputSet = new Set(json.targetDefaults.lint.inputs);
188	        inputSet.add(`{workspaceRoot}/eslint.config.${format}`);
189	        json.targetDefaults.lint.inputs = Array.from(inputSet);
190	      }
191	      if (json.targetDefaults?.['@nx/eslint:lint']?.inputs) {
192	        const inputSet = new Set(json.targetDefaults['@nx/eslint:lint'].inputs);
193	        inputSet.add(`{workspaceRoot}/eslint.config.${format}`);
194	        json.targetDefaults['@nx/eslint:lint'].inputs = Array.from(inputSet);
195	      }
196	      if (json.namedInputs?.production) {
197	        const inputSet = new Set(json.namedInputs.production);
198	        inputSet.add(`!{projectRoot}/eslint.config.${format}`);
199	        json.namedInputs.production = Array.from(inputSet);
200	      }
201	      return json;
202	    });
203	  }
204	}
