11	/**
12	 * Supports direct identifiers, and those nested within an object (of arbitrary depth)
13	 * E.g. `...foo` and `...foo.bar.baz.qux` etc
14	 */
15	const SPREAD_ELEMENTS_REGEXP = /\s*\.\.\.[a-zA-Z0-9_]+(\.[a-zA-Z0-9_]+)*,?\n?/g;
16	
17	/**
18	 * Remove all overrides from the config file
19	 */
20	export function removeOverridesFromLintConfig(content: string): string {
21	  const source = ts.createSourceFile(
22	    '',
23	    content,
24	    ts.ScriptTarget.Latest,
25	    true,
26	    ts.ScriptKind.JS
27	  );
28	
29	  const format = content.includes('export default') ? 'mjs' : 'cjs';
30	
31	  const exportsArray =
32	    format === 'mjs' ? findExportDefault(source) : findModuleExports(source);
33	  if (!exportsArray) {
34	    return content;
35	  }
36	
37	  const changes: StringChange[] = [];
38	  exportsArray.forEach((node, i) => {
39	    if (isOverride(node)) {
40	      const commaOffset =
41	        i < exportsArray.length - 1 || exportsArray.hasTrailingComma ? 1 : 0;
42	      changes.push({
43	        type: ChangeType.Delete,
44	        start: node.pos,
45	        length: node.end - node.pos + commaOffset,
46	      });
47	    }
48	  });
49	
50	  return applyChangesToString(content, changes);
51	}
52	
53	// TODO Change name
54	function findExportDefault(source: ts.SourceFile): ts.NodeArray<ts.Node> {
55	  return ts.forEachChild(source, function analyze(node) {
56	    if (
57	      ts.isExportAssignment(node) &&
58	      ts.isArrayLiteralExpression(node.expression)
59	    ) {
60	      return node.expression.elements;
61	    }
62	  });
63	}
64	
65	function findModuleExports(source: ts.SourceFile): ts.NodeArray<ts.Node> {
66	  return ts.forEachChild(source, function analyze(node) {
67	    if (
68	      ts.isExpressionStatement(node) &&
69	      ts.isBinaryExpression(node.expression) &&
70	      node.expression.left.getText() === 'module.exports' &&
71	      ts.isArrayLiteralExpression(node.expression.right)
72	    ) {
73	      return node.expression.right.elements;
74	    }
75	  });
76	}
