78	export function addPatternsToFlatConfigIgnoresBlock(
79	  content: string,
80	  ignorePatterns: string[]
81	): string {
82	  const source = ts.createSourceFile(
83	    '',
84	    content,
85	    ts.ScriptTarget.Latest,
86	    true,
87	    ts.ScriptKind.JS
88	  );
89	  const format = content.includes('export default') ? 'mjs' : 'cjs';
90	  const exportsArray =
91	    format === 'mjs' ? findExportDefault(source) : findModuleExports(source);
92	  if (!exportsArray) {
93	    return content;
94	  }
95	  const changes: StringChange[] = [];
96	  for (const node of exportsArray) {
97	    if (!isFlatConfigIgnoresBlock(node)) {
98	      continue;
99	    }
100	
101	    const start = node.properties.pos + 1; // keep leading line break
102	    const data = parseTextToJson(node.getFullText());
103	    changes.push({
104	      type: ChangeType.Delete,
105	      start,
106	      length: node.properties.end - start,
107	    });
108	    data.ignores = Array.from(
109	      new Set([...(data.ignores ?? []), ...ignorePatterns])
110	    );
111	    changes.push({
112	      type: ChangeType.Insert,
113	      index: start,
114	      text:
115	        '    ' +
116	        JSON.stringify(data, null, 2)
117	          .slice(2, -2) // Remove curly braces and start/end line breaks
118	          .replaceAll(/\n/g, '\n    '), // Maintain indentation
119	    });
120	    break;
121	  }
122	  return applyChangesToString(content, changes);
123	}
