125	export function hasFlatConfigIgnoresBlock(content: string): boolean {
126	  const source = ts.createSourceFile(
127	    '',
128	    content,
129	    ts.ScriptTarget.Latest,
130	    true,
131	    ts.ScriptKind.JS
132	  );
133	  const format = content.includes('export default') ? 'mjs' : 'cjs';
134	  const exportsArray =
135	    format === 'mjs' ? findExportDefault(source) : findModuleExports(source);
136	  if (!exportsArray) {
137	    return false;
138	  }
139	
140	  return exportsArray.some(isFlatConfigIgnoresBlock);
141	}
142	
143	function isFlatConfigIgnoresBlock(
144	  node: ts.Node
145	): node is ts.ObjectLiteralExpression {
146	  return (
147	    ts.isObjectLiteralExpression(node) &&
148	    node.properties.length === 1 &&
149	    (node.properties[0].name.getText() === 'ignores' ||
150	      node.properties[0].name.getText() === '"ignores"') &&
151	    ts.isPropertyAssignment(node.properties[0]) &&
152	    ts.isArrayLiteralExpression(node.properties[0].initializer)
153	  );
154	}
155	
156	function isOverride(node: ts.Node): boolean {
157	  return (
158	    (ts.isObjectLiteralExpression(node) &&
159	      node.properties.some(
160	        (p) => p.name.getText() === 'files' || p.name.getText() === '"files"'
161	      )) ||
162	    // detect ...compat.config(...).map(...)
163	    (ts.isSpreadElement(node) &&
164	      ts.isCallExpression(node.expression) &&
165	      ts.isPropertyAccessExpression(node.expression.expression) &&
166	      ts.isArrowFunction(node.expression.arguments[0]) &&
167	      ts.isParenthesizedExpression(node.expression.arguments[0].body))
168	  );
169	}
