171	export function hasOverride(
172	  content: string,
173	  lookup: (override: Linter.ConfigOverride<Linter.RulesRecord>) => boolean
174	): boolean {
175	  const source = ts.createSourceFile(
176	    '',
177	    content,
178	    ts.ScriptTarget.Latest,
179	    true,
180	    ts.ScriptKind.JS
181	  );
182	  const format = content.includes('export default') ? 'mjs' : 'cjs';
183	  const exportsArray =
184	    format === 'mjs' ? findExportDefault(source) : findModuleExports(source);
185	  if (!exportsArray) {
186	    return false;
187	  }
188	  for (const node of exportsArray) {
189	    if (isOverride(node)) {
190	      let data: Partial<Linter.ConfigOverride<Linter.RulesRecord>>;
191	
