    eslintFile,
    `eslint.config.${format}`,
    format,
    ignorePath
  );
  eslintIgnoreFiles.add(`${projectConfig.root}/.eslintignore`);
  if (ignorePath) {
    eslintIgnoreFiles.add(ignorePath);
  }
}

