 * Rewrites a single legacy eslint filename reference (`.eslintrc.json`,
 * `.eslintrc.base.json` or `.eslintignore`) to its flat config equivalent,
 * preserving any leading negation prefix (e.g. `!{projectRoot}/...`).
 */
function renameLegacyEslintReference(
  input: string,
  format: 'cjs' | 'mjs'
): string {
  const isNegated = input.startsWith('!');
  const value = isNegated ? input.slice(1) : input;

  // Order matters: `.eslintrc.base.json` must be checked before `.eslintrc.json`.
  const renames: Array<[string, string]> = [
    ['.eslintrc.base.json', `eslint.base.config.${format}`],
    ['.eslintrc.json', `eslint.config.${format}`],
    ['.eslintignore', `eslint.config.${format}`],
  ];

  for (const [legacy, replacement] of renames) {
    if (value.endsWith(legacy)) {
      const renamed = value.slice(0, -legacy.length) + replacement;
      return isNegated ? `!${renamed}` : renamed;
    }
  }

  return input;
}

/**
 * Rewrites legacy eslint filename references within an `inputs`/`namedInputs`
 * array to their flat config equivalents. Non-string entries (e.g. objects
 * like `{ runtime: 'node --version' }`) are left untouched. After rewriting,
 * duplicate string entries are de-duplicated. Returns the updated array, or
 * `null` when no legacy reference was found (leaving the original untouched).
 */
function rewriteEslintInputsArray(
  inputs: unknown[],
  format: 'cjs' | 'mjs'
): unknown[] | null {
  let anyRenamed = false;
  const renamed = inputs.map((entry) => {
    if (typeof entry !== 'string') {
      return entry;
    }
    const next = renameLegacyEslintReference(entry, format);
    if (next !== entry) {
      anyRenamed = true;
    }
    return next;
  });

  if (!anyRenamed) {
    return null;
  }

  // Deduplicate string entries while preserving order and non-string entries.
  const seen = new Set<string>();
  const result: unknown[] = [];
  for (const entry of renamed) {
    if (typeof entry !== 'string') {
      result.push(entry);
      continue;
    }
    if (seen.has(entry)) {
      continue;
    }
    seen.add(entry);
    result.push(entry);
  }

  return result;
}

// rewrite stale legacy eslint references in a project's targets inputs and namedInputs
function updateProjectInputsConfig(
  tree: Tree,
  project: string,
  projectConfig: ProjectConfiguration,
  format: 'cjs' | 'mjs'
) {
  let changed = false;

  if (projectConfig.targets) {
    for (const target of Object.keys(projectConfig.targets)) {
      const inputs = projectConfig.targets[target]?.inputs;
      if (Array.isArray(inputs)) {
        const rewritten = rewriteEslintInputsArray(inputs, format);
        if (rewritten) {
          projectConfig.targets[target].inputs = rewritten as any;
          changed = true;
        }
      }
    }
  }

  if (projectConfig.namedInputs) {
    for (const name of Object.keys(projectConfig.namedInputs)) {
      const inputs = projectConfig.namedInputs[name];
      if (Array.isArray(inputs)) {
        const rewritten = rewriteEslintInputsArray(inputs, format);
        if (rewritten) {
          projectConfig.namedInputs[name] = rewritten as any;
          changed = true;
        }
      }
    }
  }

  if (changed) {
    updateProjectConfiguration(tree, project, projectConfig);
  }
}

